from collections import Counter
def f(g):
    h=len(g); w=len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # candidate blocks: connected components of non-bg colors forming big rectangles; pick largest area component
    seen=[[False]*w for _ in range(h)]
    best=None
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; comp=[]; st=[(i,j)]; seen[i][j]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                area=len(comp)
                if best is None or area>best[0]: best=(area,c,min(rs),max(rs),min(cs),max(cs))
    _,c,r0,r1,c0,c1=best
    out=[row[:] for row in g]
    # perimeter cycle: encode positions of block cells on the border of bbox, ordered, skip interior duplicates
    per=[]; 
    for j in range(c0,c1+1): per.append((r0,j))
    for i in range(r0+1,r1): per.append((i,c1))
    for j in range(c1-1,c0-1,-1): per.append((r1,j))
    for i in range(r1-1,r0-1,-1): per.append((i,c0))
    n=len(per)
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v==bg or (r0<=i<=r1 and c0<=j<=c1): continue
            # relative position along perimeter: place stray at min-distance perimeter cell
            best_t=999; best_p=None
            for t,(pi_,pj_) in enumerate(per):
                d=min(abs(pi_-i)+abs(pj_-j), n-abs(pi_-i)+abs(pj_-j))
                if d<best_t: best_t,dv=best_t,pj_; best_p=(pi_,pj_); best_t=d
            out[best_p[0]][best_p[1]]=v
    return out
